const D = { density: .55, energy: .6, hue: 300, speed: 1, scale: 1, warp: .3, x: .5, y: .46, seed: 0, style: 'neon', act: 'cruise' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const TAU = 6.28318530718;
const cl = (v,a,b) => v<a?a:v>b?b:v;
const sty = P.style;
const hz = cl(P.y, .28, .72) * height;
const cx = cl(P.x, .05, .95) * width;
const groundH = Math.max(20, height - hz);
const yOf = t => hz + Math.pow(t, 1.7) * groundH;
const hwOf = t => width * (.045 + t * .95) * .5 * P.scale;
const NR = Math.round(9 + P.density * 34);
const NC = Math.round(6 + P.density * 18);

// audio-smoothed, blended on top of clk baseline
S.bass = (S.bass||0)*.8 + (A.bass||0)*.2;
S.tre  = (S.tre||0)*.8 + (A.treble||0)*.2;
const glow = (.4 + .6*P.energy) * (.55 + .55*K.intensity);
const kick = Math.min(1, K.pulse*(.5+.5*K.intensity) + S.bass*.7);

// real-time scroll floor (integrate real seconds -> never re-phases)
if (S.pt == null || K.t < S.pt) S.pt = K.t;
let dt = K.t - S.pt; S.pt = K.t; dt = cl(dt, 0, .1);
let sp = P.speed * (.55 + .8*K.intensity);
if (P.act === 'pulse') sp *= 1 + 1.1*kick;
if (P.act === 'tide')  sp *= .35 + .95*(.5 + .5*Math.sin(K.t*.06 + K.section*.9));
S.scroll = (S.scroll||0) + dt*sp*.62;
const scroll = S.scroll;

// palettes per style
const H = P.hue;
const P2 = (H + 150) % 360;                 // complement-ish accent
const isDark = sty!=='thermal';

// ---- cached structural base (plane gradient + static texture) ----
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+P.seed+'|'+Math.round(P.density*8)+'|'+Math.round(P.y*24)+'|'+Math.round(P.scale*8)+'|'+Math.round(P.warp*8);
if (!S.base || S.key !== key) {
  const g = S.base && S.base.width===width && S.base.height===height ? S.base : createGraphics(width, height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  // sky/void above horizon
  const STR = 54;
  for (let i=0;i<STR;i++){ const f=i/STR, y=f*hz;
    let h,s,b;
    if (sty==='thermal'){ h= 230-120*f; s=70; b=8+10*f; }
    else if (sty==='blueprint'){ h=P.hue; s=64; b=14+8*f; }
    else if (sty==='noir'){ h=0; s=0; b=4+9*f; }
    else { h=(H+40*f)%360; s=55; b=4+9*(1-f); }
    g.fill(h,s,b,100); g.rect(0,y,width,hz/STR+1);
  }
  // horizon glow band
  if (sty!=='blueprint'){ g.push(); g.blendMode(ADD);
    for(let i=0;i<7;i++){ const r=(7-i)*groundH*.05; const bb= sty==='noir'?60:70;
      g.fill(sty==='thermal'?45:H, sty==='noir'?0:80, bb, 9);
      g.rect(0, hz-r*.35, width, r); } g.pop(); }
  // ground plane gradient
  for (let i=0;i<STR;i++){ const f=i/STR, t=f, y=yOf(t), y2=yOf((i+1)/STR);
    let h,s,b;
    if (sty==='thermal'){ h= 250-250*Math.pow(t,1.3); s=85; b=14+70*Math.pow(t,1.6); if(t>.82){h=45;s=30-100*(t-.82);b=94;} }
    else if (sty==='blueprint'){ h=P.hue; s=60; b=16+14*t; }
    else if (sty==='noir'){ h=0; s=0; b=6+30*Math.pow(t,1.4); }
    else { h=(H+30*t)%360; s=48-20*t; b=7+16*Math.pow(t,1.3); }
    g.fill(h,s,cl(b,2,90),100); g.rect(0,y,width,(y2-y)+1);
  }
  // static texture per style
  g.push();
  if (sty==='noir'){ // wet-asphalt speckle reflections
    g.blendMode(ADD);
    for(let i=0;i<140;i++){ const t=.15+.85*fr(i*2), y=yOf(t), hw=hwOf(t);
      const x=cx+(fr(i*2+1)*2-1)*hw; g.fill(0,0,90,4+8*t); g.rect(x-.5*t*4,y, 1+t*4, t*18); } }
  else if (sty==='blueprint'){ // graph ticks above horizon
    g.stroke(P.hue,45,60,26); g.strokeWeight(1);
    for(let i=1;i<10;i++){ const y=i/10*hz; g.line(0,y,width,y); }
    for(let i=1;i<16;i++){ const x=i/16*width; g.line(x,0,x,hz); } g.noStroke(); }
  else if (sty==='thermal'){ // faint hot noise
    g.blendMode(ADD);
    for(let i=0;i<90;i++){ const t=fr(i*3), y=yOf(.1+.9*t), x=fr(i*3+1)*width;
      g.fill(30+40*t,80,90,5); g.ellipse(x,y,6+t*10,6+t*10); } }
  else { // neon starfield above horizon
    g.blendMode(ADD);
    for(let i=0;i<70;i++){ const x=fr(i*5)*width, y=fr(i*5+1)*hz*.94, m=fr(i*5+2);
      g.fill((H+120*m)%360,60,90,20+40*m); g.ellipse(x,y,1+m*2.4,1+m*2.4); } }
  g.pop();
  S.base = g; S.key = key;
}
image(S.base, 0, 0);

// ---- live animated grid + particles ----
noFill();
const warp = P.warp;
const wx = (u, t) => { const d = (u-0.5); return cx + d*width*(.03 + t*t*1.9)*P.scale * (1 + warp*1.3*d*d*4*(1-t)); };

// scanning horizontal rows
for (let r=0; r<=NR; r++){
  let t = (r - ((scroll)%1)) / NR;
  if (t<=0.0 || t>1) continue;
  const y = yOf(t), hw = hwOf(t);
  const near = t;
  let h,s,b,a,sw;
  if (sty==='neon'){ h=H; s=90; b=100; a=18+70*near; sw=.6+near*2.6; }
  else if (sty==='thermal'){ h=250-250*Math.pow(t,1.3); s=90; b=100; a=14+55*near; sw=.6+near*2.2; }
  else if (sty==='blueprint'){ h=P.hue; s=30; b=96; a=22+50*near; sw=.5+near*1.4; }
  else { h=0; s=0; b=100; a=10+52*near; sw=.5+near*2.2; } // noir
  stroke(h,s,b, a*(.6+.6*glow));
  strokeWeight(sw);
  if (sty==='neon'){ drawingContext.shadowBlur = (6+18*near)*glow; drawingContext.shadowColor = color(h,s,100,90).toString(); }
  line(cx-hw, y, cx+hw, y);
}
drawingContext.shadowBlur = 0;

// converging verticals
for (let c=0; c<=NC; c++){
  const u = c/NC;
  let h,s,b,a,sw;
  if (sty==='neon'){ h=P2; s=90; b=100; a=42; sw=1.4; }
  else if (sty==='thermal'){ h=20; s=80; b=95; a=30; sw=1.1; }
  else if (sty==='blueprint'){ h=P.hue; s=28; b=96; a=40; sw=.9; }
  else { h=0; s=0; b=100; a=26; sw=1.1; }
  stroke(h,s,b, a*(.6+.5*glow));
  strokeWeight(sw);
  if (sty==='neon'){ drawingContext.shadowBlur = 8*glow; drawingContext.shadowColor = color(h,s,100,80).toString(); }
  line(wx(u,0)*.001+cx*.999, hz, wx(u,1), height);
}
drawingContext.shadowBlur = 0;

// rising light motes / embers (continuous travel)
const NP = Math.round(P.density * 74);
push(); blendMode(ADD); noStroke();
for (let i=0;i<NP;i++){
  const lane = fr(i*4);
  const spd = .5 + fr(i*4+1)*1.1;
  let prog = (fr(i*4+2) + scroll*.14*spd) % 1;
  const t = 1 - prog;                 // travels from viewer up toward horizon
  if (t<=.02) continue;
  const y = yOf(t), hw = hwOf(t);
  const x = cx + (lane*2-1)*hw*.96 + Math.sin(K.t*.6 + i)*hw*.03;
  const sz = (1.4 + 6*t) * (1 + .6*S.tre);
  let h = sty==='thermal' ? (18+40*t) : sty==='noir' ? 0 : (H + 160*fr(i*4+3))%360;
  let s = sty==='noir' ? 0 : 80;
  const a = (10 + 40*t) * (.5+.9*glow) * (.7 + .8*fr(i*4+1));
  fill(h, s, 100, Math.min(46, a));
  ellipse(x, y, sz, sz);
}
pop();

// horizon flare pump on the beat (partial-frame, safe for strobe gate)
push(); blendMode(ADD); noStroke();
const flare = (kick*.7 + K.swell*.3) * glow;
const fh = sty==='thermal'?45 : sty==='noir'?0 : H;
for (let i=0;i<5;i++){ const rr=(5-i)*groundH*.045*(1+flare);
  fill(fh, sty==='noir'?0:70, sty==='noir'?85:95, 4+9*flare);
  rect(0, hz-rr*.4, width, rr); }
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
